#nullable enable

namespace Allocation.Views;

/// <summary>
/// `status:string` on both todo Views is a fold over event PRESENCE, and the model says which events
/// without saying what the values are — because example values are not model content. These are them.
///
/// TWO VALUES, NOT THREE. It is tempting to distinguish Issued from Refused on SlotsToIssue, and it would
/// be a second source of truth: whether a grant was issued or refused is already an event, and a projection
/// that re-states it invites a reader to trust the row over the stream. What this list has to answer is
/// only "is there work here", so it answers only that.
/// </summary>
public static class WorkStatus
{
    /// <summary>On the list. The trigger will pick this row up on its next run — and every run after,
    /// until something closes it.</summary>
    public const string Pending = "Pending";

    /// <summary>Off the list. Closed by whichever event answers the row, however it answered.</summary>
    public const string Done = "Done";
}
